export function dynamicBranchEvaluator(treeData, graphData) {
  const branchScores = treeData.map(branch => calculateConfidenceScore(branch));
  const graphUpdates = graphData.updateWithBranchScores(branchScores);
  return graphUpdates;
}

function calculateConfidenceScore(branch) {
  const entropy = branch.calculateEntropy();
  return 1 - entropy; // Higher confidence for lower entropy
}
